<script lang="ts">
import MappingPanel,{type MappingSnapshot,type MappingChange}from'./MappingPanel.svelte';
import TrayPreferences from'./TrayPreferences.svelte';
import DeviceSettings from './DeviceSettings.svelte';
import type {SettingsSnapshot} from './settings';
import {macroKeyOptions} from './macroDraft.js';
const keyboard=new URLSearchParams(location.search).get('mappingPreview')==='keyboard';
let fixture:MappingSnapshot={deviceId:'sample-only',model:keyboard?'KX75 样本':'ATK 样本',sampledAt:Date.now(),stateToken:'fixture-state',buttons:keyboard?[]:[{id:'left',label:'左键',currentAction:'leftClick',currentLabel:'左键单击',editable:true,rawHex:'01000000'},{id:'side1',label:'侧键 1',currentAction:'back',currentLabel:'后退',editable:true,rawHex:'05000000'},{id:'unknown',label:'未知按钮',currentAction:null,currentLabel:'未识别的原始映射',editable:false,rawHex:'feab1200'}],actions:[{id:'leftClick',label:'左键单击'},{id:'back',label:'后退'},{id:'forward',label:'前进'}],unsupported:[{id:'shortcut',reason:keyboard?'KX75 映射读写协议尚未闭合，暂不开放写入。':'组合快捷键编码尚未验证，暂不开放写入。'}]};
if(!keyboard){fixture.shortcutSupport={maxModifiers:2,maxActions:6,keyCodeMin:4,keyCodeMax:39,modifiers:[1,2,4,8]};fixture.actions.push({id:'shortcut',label:'组合快捷键'});fixture.unsupported=[];}
else{const ids=['Esc','F1','F2','F3','F4','F5','F6','F7','F8','F9','F10','F11','F12','Insert','Delete','backquote','one','two','three','four','five','six','seven','eight','nine','zero','transverse','equal','Backspace','Home','Tab','Q','W','E','R','T','Y','U','I','O','P','left_bracket','right_bracket','backslash','PgUp','Caps','A','S','D','F','G','H','J','K','L','semicolon','singlequotes','Enter','PgDn','Left_Shift','Z','X','C','V','B','N','M','comma','dot','slash','Right_Shift','up','Left_Ctrl','Left_Win','Left_Alt','Space','Fn','Right_Ctrl','left','down','right'];fixture.buttons=ids.map(id=>({id,label:id,currentAction:`key:${id==='Home'?'Print':id}`,currentLabel:id==='Home'?'Print':id,editable:id!=='Fn',rawHex:'00000004'}));fixture.actions=[...ids.map(id=>({id:`key:${id}`,label:id,category:'base'})),{id:'mouse:leftClick',label:'鼠标左键',category:'mouse'},{id:'media:playPause',label:'播放 / 暂停',category:'media'},{id:'taskManager',label:'任务管理器（预设）',category:'extended'},{id:'security',label:'安全选项（预设）',category:'extended'}];fixture.unsupported=[{id:'custom',reason:'开发样本只验证界面；真实能力以设备读取结果为准。'}];}
if(!keyboard){fixture.buttons=['left','right','center','side1','side2','bottom'].map((id,i)=>({id,label:['左键','右键','中键','侧键 1','侧键 2','底部按键'][i],currentAction:['leftClick','rightClick','middleClick','back','forward','dpiCycle'][i],currentLabel:['左键单击','右键单击','中键单击','后退','前进','DPI 循环'][i],editable:true}));fixture.actions=[{id:'leftClick',label:'左键单击',category:'mouse'},{id:'rightClick',label:'右键单击',category:'mouse'},{id:'middleClick',label:'中键单击',category:'mouse'},{id:'back',label:'后退',category:'mouse'},{id:'forward',label:'前进',category:'mouse'},{id:'shortcut',label:'组合快捷键',category:'shortcut'},{id:'dpiCycle',label:'DPI 循环',category:'dpi'},{id:'volumeUp',label:'音量增加',category:'media'}];fixture.keyboardOptions=macroKeyOptions('key').map(item=>({value:item.code,label:item.label,category:'keyboard'}));}
let shown=$state(true);
let settings:SettingsSnapshot={deviceId:'sample-only',sampledAt:Date.now(),stateToken:'sample-settings',fields:[{key:'reportRateHz',label:'回报率设置（Hz）',kind:'select',available:true,value:1000,options:[{label:'250 Hz',value:250},{label:'500 Hz',value:500},{label:'1000 Hz',value:1000}]},...(keyboard?[{key:'sleepSeconds',label:'休眠设置（秒）',kind:'number' as const,available:true,value:120,min:0,max:1200,step:30}]:[])]};
if(keyboard)settings.fields.push(...['lowLatency','macMode','winLock'].map((key,index)=>({key,label:['低延迟模式','Mac 模式','Win 键锁定'][index],kind:'select' as const,available:true,value:0,options:[{label:'关闭',value:0},{label:'开启',value:1}]})),{key:'dpiLevel',label:'鼠标专属 DPI 档位',kind:'number',available:false,value:null},{key:'lightingBrightness',label:'灯光专属亮度',kind:'number',available:false,value:null});
async function applySettings(_id:string,change:Record<string,unknown>){settings={...settings,fields:settings.fields.map(field=>field.key in change?{...field,value:(typeof change[field.key]==='boolean'?Number(change[field.key]):change[field.key]) as number}:field)};return settings;}
async function apply(_id:string,c:MappingChange){if(c.expectedState!==fixture.stateToken)throw Error('样本快照过期');fixture={...fixture,stateToken:'fixture-'+Date.now(),buttons:fixture.buttons.map(b=>b.id===c.buttonId?{...b,currentAction:c.action,shortcut:c.shortcut,currentLabel:c.action==='shortcut'?'样本组合键':fixture.actions.find(a=>a.id===c.action)?.label||c.action}:b)};return fixture;}
</script>
<div class="shell" style="height:100vh;overflow:auto"><div style="max-width:1120px;margin:auto;padding:24px"><h2>设备设置 · 开发样本</h2><p>不连接设备，不发送原生命令。工作区随组件挂载直接打开。</p>{#if shown}<DeviceSettings open={true} model={keyboard?'迈从 KX75':'ATK F1'} deviceId="sample-only" onclose={()=>shown=false} load={async()=>settings} apply={applySettings} mappingAdapter={{load:async()=>fixture,apply}} sample/>{:else}<button onclick={()=>shown=true}>重新打开样本</button>{/if}<div style="margin-top:24px"><MappingPanel deviceId="sample-only" load={async()=>fixture} {apply} sample={true} {keyboard}/></div><details><summary>托盘偏好样本</summary><TrayPreferences sample={true}/></details></div></div>
